def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]}).body["order_id"]


def test_order_history_for_unknown_customer_is_not_found(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_for_customer_without_orders_is_empty(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_lists_newest_order_first(shop):
    first = order(shop, "c1", ("PEN", 1))
    second = order(shop, "c1", ("BOOK", 1))
    orders = shop.insights.handle_order_history("c1").body["orders"]
    assert [entry["order_id"] for entry in orders] == [second, first]


def test_order_history_total_matches_order_summary_including_discount(shop):
    order_id = order(shop, "c1", ("BOOK", 4))
    summary_total = shop.orders.handle_get(order_id).body["total_cents"]
    entry = shop.insights.handle_order_history("c1").body["orders"][0]
    assert entry["total_cents"] == summary_total == 9_000


def test_order_history_includes_cancelled_orders_with_their_status(shop):
    order_id = order(shop, "c1", ("PEN", 2))
    shop.orders.handle_cancel(order_id)
    orders = shop.insights.handle_order_history("c1").body["orders"]
    assert orders == [{"order_id": order_id, "status": "cancelled", "total_cents": 600}]


def test_order_history_entries_only_contain_order_fields(shop):
    order(shop, "c2", ("LAMP", 1))
    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert set(entry) == {"order_id", "status", "total_cents"}

