def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]}).body["order_id"]


@pytest.mark.parametrize("limit", [0, -1, "3", 2.0, None, True])
def test_top_customers_rejects_a_limit_that_is_not_a_positive_integer(shop, limit):
    response = shop.insights.handle_top_customers(limit)
    assert response.status == 400
    assert "limit" in response.body["error"]


def test_top_customers_ranks_by_lifetime_value_highest_first(shop):
    order(shop, "c1", ("BOOK", 4))
    order(shop, "c2", ("LAMP", 2))
    response = shop.insights.handle_top_customers(10)
    assert response.status == 200
    assert response.body == {"customers": [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 10_200},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 9_000},
    ]}


